{
    IQueryable<Task> result;
    UserBack myUser;
    if (!IsAuth(out myUser))
        return new List<Task>().AsQueryable();
    try
    {
        DateTime start = startI.ToUniversalTime();
        DateTime end = endI.ToUniversalTime();
        if (end.Hour != 0)
        {
            start = new DateTime(startI.Year, startI.Month, startI.Day, 0, 0, 0);
            end = new DateTime(endI.Year, endI.Month, endI.Day, 23, 59, 0);
        }
        if (myUser.IsSystemManager==true)
        {
            result=(from job in _db.Context.Jobs.DefaultIfEmpty()
                    join task in _db.Context.Tasks on job.ParentId equals task.Id
                    where   (job.start == null || (job.start <= end && job.end >= start)) && task.MainUserId == myUser.MainUserId && job.MainUserId == myUser.MainUserId 
                    select task
                    ).Union(_db.Context.Tasks.Where(c => !_db.Context.Jobs.Select(b => b.ParentId).Contains(c.Id) && c.MainUserId==myUser.MainUserId));

        }
        else if (myUser.IsClientManager==true)
        {
            string Client = myUser.Client;
            string[] Clients = Client.Split(',');
            result=(from job in _db.Context.Jobs join task in _db.Context.Tasks on job.ParentId equals task.Id where  Clients.Contains(task.Client) && job.start <= end && job.end >= start && task.MainUserId == myUser.MainUserId && job.MainUserId == myUser.MainUserId  select task)
               .Union(_db.Context.Tasks.Where(c => Clients.Contains(c.Client) && !_db.Context.Jobs.Select(b => b.ParentId).Contains(c.Id)));

        }
        else if (myUser.IsFilialManager==true)
        {
            string Filial = myUser.Filial;
            result=(from job in _db.Context.Jobs join task in _db.Context.Tasks on job.ParentId equals task.Id where   task.Filial == Filial && job.start <= end && job.end >= start && task.MainUserId == myUser.MainUserId && job.MainUserId == myUser.MainUserId  select task)
                .Union(_db.Context.Tasks.Where(c =>c.Filial==Filial && !_db.Context.Jobs.Select(b => b.ParentId).Contains(c.Id) && c.MainUserId==myUser.MainUserId)); 
        }
        else
        {
            string MemberId = myUser.Id.ToString();
            result=(from job in _db.Context.Jobs join task in _db.Context.Tasks  on job.ParentId equals task.Id where  job.MemberId == MemberId && job.start <= end && job.end >= start && task.MainUserId == myUser.MainUserId && job.MainUserId == myUser.MainUserId select task);
        }

        return result;
    }
    catch (Exception em)
    {
        return new List<Task>().AsQueryable();
    }
}

