                myMove.Explanation = actionWithStates.action.Title;
                myMove.ActionId = actionWithStates.action.Id.ToString();
                myMove.StateId = stateRequirement.id.ToString();
                myMove.ActionNum = myTeam.ActionNum;
                myMove.CardId = actionWithStates.action.ParentId;
                _context.TeamHistoryMoves.Add(myMove);


            }
            _context.SaveChanges();

        }
